function validate([poly1, poly2]) {
  for (const [name, poly] of [['poly1', poly1], ['poly2', poly2]]) {
    if (!Array.isArray(poly) || poly.length < 1 || poly.length > 50000) return `${name} needs 1 to 5 * 10^4 coefficients.`;
    if (poly.some(c => !Number.isInteger(c) || c < -1000 || c > 1000)) return `Each coefficient of ${name} is between -1000 and 1000.`;
    if (poly.every(c => c === 0)) return `${name} needs at least one non-zero coefficient.`;
  }
  return null;
}

