function multiply(poly1, poly2) {
  const length = poly1.length + poly2.length - 1;
  let size = 1;
  while (size < length) size *= 2;

  const transform = (values, sign) => {
    const n = values.length;
    if (n === 1) return values;
    const half = n / 2;
    const even = transform(values.filter((_, i) => i % 2 === 0), sign);
    const odd = transform(values.filter((_, i) => i % 2 === 1), sign);
    const result = new Array(n);
    for (let k = 0; k < half; k++) {
      const angle = (sign * Math.PI * k) / half;
      const wRe = Math.cos(angle);
      const wIm = Math.sin(angle);
      const [evenRe, evenIm] = even[k];
      const [oddRe, oddIm] = odd[k];
      const twistRe = wRe * oddRe - wIm * oddIm;
      const twistIm = wRe * oddIm + wIm * oddRe;
      result[k] = [evenRe + twistRe, evenIm + twistIm];
      result[k + half] = [evenRe - twistRe, evenIm - twistIm];
    }
    return result;
  };

  const toComplex = poly => Array.from({ length: size }, (_, i) => [i < poly.length ? poly[i] : 0, 0]);
  const a = transform(toComplex(poly1), 1);
  const b = transform(toComplex(poly2), 1);
  const product = a.map(([aRe, aIm], i) => {
    const [bRe, bIm] = b[i];
    return [aRe * bRe - aIm * bIm, aRe * bIm + aIm * bRe];
  });
  const values = transform(product, -1);
  const result = [];
  for (let i = 0; i < length; i++) {
    result.push(Math.round(values[i][0] / size));
  }
  return result;
}

