function multiply(poly1, poly2) {
  // Schoolbook multiplication: each pair of terms adds its product to the coefficient of x^(i + j).
  const result = new Array(poly1.length + poly2.length - 1).fill(0);
  for (let i = 0; i < poly1.length; i++) {
    for (let j = 0; j < poly2.length; j++) result[i + j] += poly1[i] * poly2[j];
  }
  return result;
}

