function generate(rand, size) {
  // One style per input: ±1000 with mostly one sign (the largest coefficients), sparse small values, or uniform values.
  const style = rand();
  const make = () => {
    const length = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
    const sign = rand() < 0.5 ? -1 : 1;
    const poly = Array.from({ length }, () => {
      if (style < 0.25) return rand() < 0.9 ? sign * 1000 : -sign * 1000;
      if (style < 0.5) return rand() < 0.7 ? 0 : Math.floor(rand() * 7) - 3;
      return Math.floor(rand() * 2001) - 1000;
    });
    // Each polynomial needs at least one non-zero coefficient.
    if (poly.every(c => c === 0)) poly[Math.floor(rand() * length)] = 1 + Math.floor(rand() * 1000);
    return poly;
  };
  return [make(), make()];
}
